    const hidden = Boolean(middlewareData.hide?.referenceHidden) || x === null || y === null;
    const arrowOffsetValue: string | number = middlewareData.arrowOffset?.value;

    return {
        reference: isOpen ? reference : null,
        floating: isOpen ? floating : null,
        position: hidden
            ? hiddenPosition
