import { RefObject } from 'react';

import { Middleware, MiddlewareArguments, MiddlewareReturn, size } from '@floating-ui/react-dom';

import { ArrowOffset, PopperPlacement, PopperPosition } from './interface';

export const allPopperPlacements: PopperPlacement[] = [
    'top-start',
    'top',
    'top-end',
    'right-start',
    'right',
    'right-end',
    'bottom-end',
    'bottom',
    'bottom-start',
    'left-end',
    'left',
    'left-start',
];

export const getInvertedRTLPlacement = (placement: PopperPlacement, rtl: boolean): PopperPlacement => {
    if (!rtl) {
        return placement;
    }

    switch (placement) {
        case 'top-start':
            return 'top-end';
        case 'top-end':
            return 'top-start';
        case 'bottom-start':
            return 'bottom-end';
        case 'bottom-end':
            return 'bottom-start';
        default:
            return placement;
    }
};

export const rtlPlacement = (): Middleware => {
    return {
        name: 'rtlPlacement',
        fn({ elements, placement }: MiddlewareArguments): MiddlewareReturn {
            const rtl = getComputedStyle(elements.floating).direction === 'rtl';

            return { data: { value: getInvertedRTLPlacement(placement, rtl) } };
        },
    };
};

const getInvertedPlacement = (placement: PopperPlacement): PopperPlacement => {
    const position = placement.split('-')[0];
    if (position === 'top') {
        return 'bottom';
    }
    if (position === 'bottom') {
        return 'top';
    }
    if (position === 'left') {
        return 'right';
    }
    if (position === 'right') {
        return 'left';
    }
    return 'top';
};

export const cornerPopperPlacements: PopperPlacement[] = [
    'top-start',
    'top-end',
    'right-start',
    'right-end',
    'bottom-end',
    'bottom-start',
    'left-end',
    'left-start',
];

