    allPopperPlacements,
    getFallbackPlacements,
    getInvertedRTLPlacement,
    rtlPlacement,
} from '@proton/components/components/popper/utils';

describe('popper utils', () => {
    describe('RTL placement', () => {
        const invertedPlacements: [PopperPlacement, PopperPlacement][] = [
            ['top-start', 'top-end'],
            ['top-end', 'top-start'],
            ['bottom-start', 'bottom-end'],
            ['bottom-end', 'bottom-start'],
        ];

        test.each(invertedPlacements)('inverts %s to %s in RTL', (placement, expected) => {
            expect(getInvertedRTLPlacement(placement, true)).toBe(expected);
        });

        test.each(allPopperPlacements.map((placement) => [placement]))('preserves %s in LTR', (placement) => {
            expect(getInvertedRTLPlacement(placement, false)).toBe(placement);
        });

        test.each(['top', 'bottom', 'left', 'left-start', 'left-end', 'right', 'right-start', 'right-end'] as PopperPlacement[])(
            'preserves %s in RTL',
            (placement) => {
                expect(getInvertedRTLPlacement(placement, true)).toBe(placement);
            }
        );

        test.each<{
            direction: 'ltr' | 'rtl';
            placement: PopperPlacement;
            expected: PopperPlacement;
        }>([
            { direction: 'rtl', placement: 'top-start', expected: 'top-end' },
            { direction: 'rtl', placement: 'bottom-end', expected: 'bottom-start' },
            { direction: 'rtl', placement: 'right-start', expected: 'right-start' },
            { direction: 'ltr', placement: 'top-start', expected: 'top-start' },
        ])('reports $expected for $placement in $direction', async ({ direction, placement, expected }) => {
            const floating = document.createElement('div');
            floating.style.direction = direction;

            const middleware = rtlPlacement();
            const result = await middleware.fn({ placement, elements: { floating } } as MiddlewareArguments);

            expect(middleware.name).toBe('rtlPlacement');
            expect(result).toMatchObject({ data: { value: expected } });
        });
    });

    test('should sort placements when given top-end', () => {
        expect(getFallbackPlacements('top-end')).toEqual([
            'top-start',
            'top',
            'bottom-end',
            'bottom',
            'bottom-start',
            'right-start',
            'right',
            'right-end',
            'left-end',
            'left',
            'left-start',
        ]);
    });

    test('should sort placements when given top', () => {
        expect(getFallbackPlacements('top')).toEqual([
            'top-start',
            'top-end',
            'bottom',
            'bottom-end',
            'bottom-start',
            'right-start',
            'right',
            'right-end',
            'left-end',
            'left',
            'left-start',
        ]);
    });

    test('should sort placements when given right', () => {
        expect(getFallbackPlacements('right')).toEqual([
            'right-start',
            'right-end',
            'left',
            'left-end',
            'left-start',
            'top-start',

    return {
        reference: isOpen ? reference : null,
        floating: isOpen ? floating : null,
        position: hidden
            ? hiddenPosition
            : {
                  top: y || 0,
                  left: x || 0,
              },
        arrow: {
            '--arrow-offset': !arrowOffsetValue ? 0 : `${arrowOffsetValue}px`,
        },
        placement: hidden ? 'hidden' : middlewareData.rtlPlacement?.value || placement,
    };
};

export default usePopper;

